// Le o resumo em JSON que o script devolve e decide se ha algo a avisar.
// Sem novidade, devolve lista vazia: os nos de notificacao nao rodam.
const cfg = $('Configuracao').first().json;
const saida = String($input.first().json.stdout || '').trim();
const linha = saida.split(/\r?\n/).filter(l => l.trim().startsWith('{')).pop();

let r;
try {
  r = JSON.parse(linha);
} catch (e) {
  r = { status: 'erro', mensagem: 'Saida inesperada do script: ' + saida.slice(0, 300), partidas_novas: [] };
}

const memoria = $getWorkflowStaticData('global');
const agora = Date.now();
const UM_DIA = 24 * 60 * 60 * 1000;
const rotulo = { V: 'Vitoria', D: 'Derrota', E: 'Empate' };
const novas = r.partidas_novas || [];
const pub = r.publicacao || {};

let assunto = null;
let texto = null;

if (novas.length) {
  const linhas = novas.map(p =>
    `${rotulo[p.resultado] || p.resultado}: FURIA ${p.placar_furia} x ${p.placar_adversario} ${p.adversario} (${p.data})\n` +
    `${p.evento || ''}\n${p.mapas || ''}`);
  const extra = r.baixadas > novas.length ? `\n\n(+${r.baixadas - novas.length} partida(s) mais antigas)` : '';
  assunto = `FURIA: ${r.baixadas} partida(s) nova(s) no dashboard`;
  texto = `${assunto}\n\n${linhas.join('\n\n')}${extra}`;
  if (pub.status === 'publicado' && cfg.url_dashboard) texto += `\n\nDashboard atualizado: ${cfg.url_dashboard}`;
}

// Problema na carga ou na publicacao do dashboard.
const problema = r.status !== 'ok' ? r.status : (pub.status === 'erro' ? 'publicacao' : null);
if (problema) {
  // O mesmo problema so e avisado de novo depois de 24 horas.
  const repetido = memoria.ultimoErro === problema && agora - (memoria.avisoErroEm || 0) < UM_DIA;
  if (!repetido) {
    const aviso = problema === 'cloudflare'
      ? 'A HLTV pediu a verificacao do Cloudflare. Resolva-a na janela do Chrome que ficou aberta; a proxima execucao continua de onde parou.'
      : problema === 'publicacao'
        ? `Os dados foram atualizados, mas o envio do dashboard ao GitHub falhou: ${pub.mensagem}`
        : `A carga diaria falhou (${r.status}): ${r.mensagem}`;
    assunto = assunto || 'FURIA: a carga diaria precisa de atencao';
    texto = texto ? `${texto}\n\n${aviso}` : `${assunto}\n\n${aviso}`;
    memoria.avisoErroEm = agora;
  }
  memoria.ultimoErro = problema;
} else {
  memoria.ultimoErro = null;
}

if (!texto) return [];
return [{ json: { ...cfg, status: r.status, assunto, texto } }];
